HttpJson IS NULL OR COALESCE(Outcome=0 AND ReasonCode='http_request_completed' AND RequestId IS NOT NULL AND length(CAST(HttpJson AS BLOB)) BETWEEN 2 AND 16384 AND json_valid(HttpJson) AND json_type(HttpJson)='object' AND json_type(HttpJson,'$.StatusCode')='integer' AND json_extract(HttpJson,'$.StatusCode') BETWEEN 100 AND 599 AND json_type(HttpJson,'$.FinalUrl')='text' AND length(json_extract(HttpJson,'$.FinalUrl')) BETWEEN 1 AND 4096 AND (json_extract(HttpJson,'$.FinalUrl') LIKE 'https://%' OR json_extract(HttpJson,'$.FinalUrl') LIKE 'http://%') AND (json_type(HttpJson,'$.ContentType')='null' OR json_type(HttpJson,'$.ContentType')='text' AND length(json_extract(HttpJson,'$.ContentType'))<=200) AND json_type(HttpJson,'$.ProjectedBodyBytes')='integer' AND json_extract(HttpJson,'$.ProjectedBodyBytes') BETWEEN 0 AND 65536 AND json_type(HttpJson,'$.BodySha256')='text' AND length(json_extract(HttpJson,'$.BodySha256'))=64 AND json_extract(HttpJson,'$.BodySha256') NOT GLOB '*[^0-9a-f]*' AND json_type(HttpJson,'$.Truncated') IN ('true','false'),0)